mapper.select:
SELECT s.*,u.display_name doctor_name,d.title,d.department_id,dep.name department_name,dep.location FROM schedule s JOIN doctor d ON d.id=s.doctor_id JOIN app_user u ON u.id=d.user_id JOIN department dep ON dep.id=d.department_id
    s.status='OPEN' AND d.enabled=true AND dep.enabled=true AND u.enabled=true AND s.start_time>#{now} AND s.work_date BETWEEN #{today} AND #{lastDay}
       AND d.department_id=#{departmentId} AND s.doctor_id=#{doctorId}
       AND s.work_date >= #{from} AND s.work_date <= #{to}
       AND s.period=#{period} AND s.status=#{status} AND s.remaining>0
       AND d.title=#{title}
       AND (u.display_name LIKE CONCAT('%',#{keyword},'%') OR d.title LIKE CONCAT('%',#{keyword},'%'))
     ORDER BY s.start_time,s.id LIMIT #{size} OFFSET #{offset}
